/*
 * SPDX-License-Identifier: MIT
 *
 * nxsplash-nextos: mandatory, backend-neutral pre-runtime screen for ports
 * generated by the NextOS framework.
 *
 * SDL2 is resolved at runtime so the helper follows the firmware provider.
 * A real inherited/default backend is always attempted first. Advertised
 * backends are considered only after that attempt fails, and a software
 * framebuffer is the graphical last-resort renderer. Failure to draw is
 * fail-open: the fixed hold still completes and the game lifecycle remains
 * untouched.
 */
#ifndef _GNU_SOURCE
#define _GNU_SOURCE
#endif

