#define NXSPLASH_DURATION_MS 5000u
#endif
#ifndef NXSPLASH_FBDEV_PATH
#define NXSPLASH_FBDEV_PATH "/dev/fb0"
#endif

#define NXSPLASH_VERSION "0.1.2"
#define MAX_VIDEO_CANDIDATES 24
#define MAX_VIDEO_DRIVER_NAME 64

typedef struct SDL_Window SDL_Window;
typedef struct SDL_Renderer SDL_Renderer;
typedef struct SDL_Rect {
  int x, y, w, h;
} SDL_Rect;
typedef union SDL_Event {
  uint32_t type;
  unsigned char padding[256];
} SDL_Event;

enum {
  SDL_INIT_VIDEO = 0x00000020u,
  SDL_WINDOW_FULLSCREEN_DESKTOP = 0x00001001u,
  SDL_RENDERER_SOFTWARE = 0x00000001u,
  SDL_RENDERER_ACCELERATED = 0x00000002u,
  SDL_RENDERER_PRESENTVSYNC = 0x00000004u,
};

typedef struct Color {
  uint8_t r, g, b, a;
} Color;

typedef struct VideoCandidates {
  char names[MAX_VIDEO_CANDIDATES][MAX_VIDEO_DRIVER_NAME];
  int count;
} VideoCandidates;

